// Parse Claude's JSON response.
const resp = $input.first().json;
const text = (resp.content || []).map(c => c.text || '').join('\n').trim();
const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
let parsed;
try { parsed = JSON.parse(cleaned); }
catch (e) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  parsed = m ? JSON.parse(m[0]) : { earnings: [], macro: [], news: [], cross_asset: [], bias_read: text };
}
for (const k of ['earnings','news','cross_asset']) if (!Array.isArray(parsed[k])) parsed[k] = [];
if (typeof parsed.bias_read !== 'string') parsed.bias_read = '';

const runType = $('Build Prompt').first().json.runType;
const itemCount = $('Build Prompt').first().json.itemCount;
const items = $('Fetch All Sources').all().map(i => i.json);
return [{ json: { ...parsed, runType, itemCount, items } }];

// Build a styled HTML document and emit it as binary for Gotenberg.
const d = $input.first().json;
const { earnings, macro, news, cross_asset, bias_read, runType, itemCount, items } = d;

const dt = new Date();
const dateStr = dt.toLocaleDateString('en-US', { timeZone: 'America/New_York', weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
const dateMono = dt.toLocaleDateString('en-US', { timeZone: 'America/New_York', month: '2-digit', day: '2-digit', year: 'numeric' });
const headerLabel = runType === 'premarket' ? 'PRE-MARKET' : 'POST-CLOSE';
const timeLabel = runType === 'premarket' ? '9:15 AM ET' : '5:45 PM ET';
const issueLabel = runType === 'premarket' ? 'AM EDITION' : 'PM EDITION';
const esc = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

const top10Items = items.filter(i => i.category === 'top10').sort((a, b) => a.rank - b.rank);
let top10Html = '';
if (top10Items.length) {
  const maxWeight = Math.max(...top10Items.map(t => t.weight));
  top10Html = '<div class="holdings"><table>';
  for (const t of top10Items) {
    const barW = ((t.weight / maxWeight) * 60).toFixed(0);
    const chCls = t.pct == null ? 'flat' : (t.pct >= 0 ? 'up' : 'dn');
    const arrow = t.pct == null ? '·' : (t.pct >= 0 ? '▲' : '▼');
    const chSign = t.pct == null ? '' : (t.pct >= 0 ? '+' : '');
    const chStr = t.pct == null ? 'n/a' : (chSign + t.pct.toFixed(2) + '%');
    const rankStr = (t.rank < 10 ? '0' : '') + t.rank;
    top10Html += '<tr>';
    top10Html += '<td class="rank">' + rankStr + '</td>';
    top10Html += '<td class="ticker">' + esc(t.ticker) + '</td>';
    top10Html += '<td class="name">' + esc(t.name || '') + '</td>';
    top10Html += '<td class="weight"><span class="weight-bar" style="width:' + barW + 'px"></span>' + t.weight.toFixed(2) + '%</td>';
    top10Html += '<td class="price">$' + (t.price || 0).toFixed(2) + '</td>';
    top10Html += '<td class="change ' + chCls + '">' + arrow + ' ' + chStr + '</td>';
    top10Html += '</tr>';
  }
  top10Html += '</table></div>';
}

const econEvents = items.filter(i => i.category === 'econ_calendar').sort((a, b) => new Date(a.eventDate) - new Date(b.eventDate));
const todayKey = dt.toLocaleDateString('en-US', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' });
const tomorrowKey = new Date(Date.now() + 86400000).toLocaleDateString('en-US', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' });
const econByDay = {};
for (const e of econEvents) {
  const ed = new Date(e.eventDate);
  const dayKey = ed.toLocaleDateString('en-US', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' });
  if (!econByDay[dayKey]) {
    let label, tagCls;
    if (dayKey === todayKey) { label = 'Today'; tagCls = 'today'; }
    else if (dayKey === tomorrowKey) { label = 'Tomorrow'; tagCls = 'tomorrow'; }
    else { label = ed.toLocaleDateString('en-US', { timeZone: 'America/New_York', weekday: 'long' }); tagCls = 'future'; }
    econByDay[dayKey] = {
      label, tagCls,
      dayName: ed.toLocaleDateString('en-US', { timeZone: 'America/New_York', weekday: 'long' }),
      dateLabel: ed.toLocaleDateString('en-US', { timeZone: 'America/New_York', month: 'short', day: 'numeric' }),
      events: []
    };
  }
  econByDay[dayKey].events.push(e);
}
let econSection = '';
const econDays = Object.values(econByDay);
if (econDays.length) {
  let econHtml = '<div class="calendar">';
  for (const g of econDays) {
    econHtml += '<div class="cal-day">';
    econHtml += '<div class="cal-day-header">';
